#include <vxnn/int16_lowering.hpp>
#include "nnrt/package/json.hpp"
#include <cstring>
#include <set>
namespace vxnn {
Result<Int16Lowered>lower_int16_node(const Plan&p,const Int16Family&family,const ArenaStorage&s,NodeId id,uint64_t sequence,uint64_t cookie){try{
 const auto&r=s.receipt();json::check(sequence&&cookie&&r.phase==ArenaStoragePhase::READY&&!r.first_error&&r.root&&s.bindings()&&r.epoch&&p.policy.hardware.device_generation==r.epoch&&vxunified::s8_provider(p.policy.hardware)&&p.plan_id==s.layout().plan_id,"owned READY integer plan/epoch required");
 json::check(p.programs.size()==1,"one integer program family");const auto&key=p.programs[0];json::check(key.namespace_id==1&&key.logical_profile==1&&key.logical_program==VXNN_MATMUL_I16&&key.code==family.program_sha&&digest_hex(key.schema)=="b4bcde7864f8b6cab955f2f98de2d558edefe27257a6465fe89aedba72a95f0d"&&bool(vxunified::admit_program(p.policy.hardware,key)),"exact integer program/schema/hardware");
 const PlannedNode*pn=nullptr;std::set<NodeId>ids;for(const auto&n:p.nodes){json::check(ids.insert(n.node.id).second,"unique integer node");if(n.node.id==id)pn=&n;}json::check(pn&&id&&pn->job_count==1&&!pn->workspace_bytes,"bounded single integer node");const auto&n=pn->node;
 uint32_t opcode=0;for(uint32_t code:{uint32_t(VXNN_MATMUL_I16),uint32_t(VXNN_BIAS_I48),uint32_t(VXNN_RELU_I48)}){auto k=int16_operator_key(code,family);if(!(k<n.key)&&!(n.key<k))opcode=code;}json::check(opcode&&n.program_requirements==std::vector<Digest>{family.program_sha},"registered integer node/program identity");
 const auto&root=*r.root;auto valid=[&](const BufferRef&b){return b.handle==root.handle&&b.object_generation==root.object_generation&&b.device_generation==r.epoch&&b.bytes&&b.offset>=r.prefix_bytes&&b.offset%2==0&&b.offset<=root.bytes&&b.bytes<=root.bytes-b.offset&&(b.access==1||b.access==2||b.access==3);};std::map<TensorId,const TensorDesc*>desc;
 for(const auto&t:p.tensors){json::check(desc.emplace(t.desc.id,&t.desc).second,"unique integer tensor");auto it=s.bindings()->tensors.find(t.desc.id);json::check(it!=s.bindings()->tensors.end()&&valid(it->second)&&it->second.bytes==t.desc.bytes&&it->second.access==t.desc.access,"owned integer tensor extent/access");}
 std::vector<TensorDesc>inputs,outputs;for(auto tid:n.inputs){json::check(desc.count(tid),"declared input");inputs.push_back(*desc.at(tid));}for(auto tid:n.outputs){json::check(desc.count(tid),"declared output");outputs.push_back(*desc.at(tid));}
 OperatorRegistry registry;auto registered=register_int16_operators(registry,family);if(!registered)return Result<Int16Lowered>::failure(*registered.error);auto op=registry.resolve(n.key.name,n.key.semantic_version,n.key.implementation_sha);if(!op)return Result<Int16Lowered>::failure(*op.error);auto prepared=op.value->prepare(id,inputs,outputs,n.parameters,p.caps);if(!prepared)return Result<Int16Lowered>::failure(*prepared.error);
 json::check(prepared.value->inputs==n.inputs&&prepared.value->outputs==n.outputs&&prepared.value->program_requirements==n.program_requirements,"prepared integer identity unchanged");
 Int16Lowered lowered;lowered.node=id;auto&a=lowered.args;a.version=1;a.bytes=128;a.op=opcode;a.m=uint32_t(outputs.at(0).shape.at(0));a.n=uint32_t(outputs.at(0).shape.at(1));a.k=opcode==VXNN_MATMUL_I16?uint32_t(inputs[0].shape[1]):0;
 auto first=s.bindings()->tensors.at(n.inputs[0]);first.access=1;auto second=opcode==VXNN_RELU_I48?first:s.bindings()->tensors.at(n.inputs[1]);second.access=1;auto output=s.bindings()->tensors.at(n.outputs[0]);output.access=2;lowered.references={first,second,output};
 auto overlaps=[](const BufferRef&a,const BufferRef&b){return a.handle==b.handle&&a.offset<b.offset+b.bytes&&b.offset<a.offset+a.bytes;};json::check(!overlaps(first,output)&&!overlaps(second,output)&&first.bytes<=UINT32_MAX&&second.bytes<=UINT32_MAX&&output.bytes<=UINT32_MAX,"nonaliasing bounded integer references");
 a.a_bytes=uint32_t(first.bytes);a.b_bytes=uint32_t(second.bytes);a.out_bytes=uint32_t(output.bytes);a.generation_low=uint32_t(r.epoch);a.generation_high=uint32_t(r.epoch>>32);a.sequence_low=uint32_t(sequence);a.sequence_high=uint32_t(sequence>>32);a.cookie_low=uint32_t(cookie);a.cookie_high=uint32_t(cookie>>32);auto binding=content_digest("INT16_NODE_V1:"+digest_hex(p.plan_id)+":"+std::to_string(id));std::memcpy(a.binding,binding.data(),16);
 return Result<Int16Lowered>::success(std::move(lowered));
 }catch(const std::bad_alloc&){return Result<Int16Lowered>::failure({ENOMEM,"INT16_LOWER","metadata allocation"});}catch(const std::exception&e){return Result<Int16Lowered>::failure({EINVAL,"INT16_LOWER",e.what()});}}
}
